import { cn } from '@cascivo/core/pure'
import { builtin, t } from '@cascivo/i18n'
import type { ReactNode } from 'react'
import { Toggletip } from '../toggletip/toggletip'
import { VisuallyHidden } from '../visually-hidden/visually-hidden'
import styles from './ai-badge.module.css'

export interface AiBadgeProps {
  children?: ReactNode
  labels?: {
    text?: string
    explain?: string
    description?: string
  }
  className?: string
}

export function AiBadge({ children, labels, className }: AiBadgeProps) {
  const text = labels?.text ?? t(builtin.aiBadge.text)
  const explain = labels?.explain ?? t(builtin.aiBadge.explain)

  if (children === undefined || children === null) {
    return (
      <span className={cn(styles['badge'], className)}>
        <span aria-hidden="true">{text}</span>
        <VisuallyHidden>{labels?.description ?? t(builtin.aiBadge.description)}</VisuallyHidden>
      </span>
    )
  }

  return (
    <Toggletip
      className={cn(styles['root'], className)}
      trigger={<span className={styles['badge']}>{text}</span>}
      // The accessible name starts with the visible text (WCAG 2.5.3 Label in Name).
      labels={{ label: `${text} ${explain}` }}
    >
      {children}
    </Toggletip>
  )
}

@layer cascivo.component {
  .root {
    vertical-align: middle;

    /* Toggletip pads its trigger for a bare icon; the pill carries its own padding. */
    & > button {
      padding: 0;
      border-radius: var(--cascivo-radius-indicator);
    }
  }

  .badge {
    display: inline-flex;
    align-items: center;
    padding-block: 0.125rem;
    padding-inline: var(--cascivo-space-1);
    border: 1px solid var(--cascivo-color-ai-border);
    border-radius: var(--cascivo-radius-indicator);
    background-color: var(--cascivo-color-ai-subtle);
    color: color-mix(in oklab, var(--cascivo-color-ai) 35%, var(--cascivo-color-text));
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-xs);
    font-weight: var(--cascivo-font-semibold);
    letter-spacing: 0.02em;
    line-height: var(--cascivo-leading-none);
    vertical-align: middle;
  }
}

@media (forced-colors: active) {
  .badge {
    border-color: CanvasText;
    color: CanvasText;
  }
}
